from PIL import Image
import glob, os
expected = {'mipmap-mdpi':48,'mipmap-hdpi':72,'mipmap-xhdpi':96,'mipmap-xxhdpi':144,'mipmap-xxxhdpi':192}
bad = []
files = sorted(glob.glob('android/app/src/main/res/mipmap-*/ic_launcher.png') +
               glob.glob('ios/Runner/Assets.xcassets/AppIcon.appiconset/*.png') +
               ['assets/images/app_logo.png'])
for f in files:
    img = Image.open(f)
    if f.startswith('android'):
        want = expected[f.split('/')[5]]
        if img.size != (want, want): bad.append((f, img.size))
    if img.size[0] != img.size[1]: bad.append((f, img.size))
    if img.mode != 'RGB': bad.append((f, 'mode ' + img.mode))  # iOS: opaque, no alpha
print(f'{len(files)} images checked; bad: {bad if bad else "none"}')
EOF"}

